import os, re

def load():
    d = os.path.normpath('/home/USER/runs/paper/qwen-hpl0-u1-turns/frozen/held-out-reference-2/play/users/u025/system/state')
    session_file = os.path.join(d, '../sessions/' + os.path.basename(d) + '.jsonl')
    t = open(session_file).read().replace('\\n', '\n')
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load()
print("Loaded grids:", sorted(G.keys()))
for k, v in G.items():
    print(f"\n{label if (label := k.replace('pair ', '').replace('input ', '')) in ['input', 'output', 'Test input'] else label}: {k}")
